// Params defines the oracle module parameters.
//
// min_submissions / max_data_age act as defaults whenever a Topic does
// not override them. max_metadata_size caps Submission.metadata bytes.
//
// bond_min_amount is the minimum coin value a provider must escrow when
// registering. bond_denom is the only denom accepted; the bond is held
// in the oracle module account.
//
// bond_release_cooldown is the number of blocks a withdrawing provider
// must wait between RequestWithdraw and WithdrawBond, giving x/dataslash
// (and governance) time to challenge.
type Params struct {
	MinSubmissions      uint32 `protobuf:"varint,1,opt,name=min_submissions,json=minSubmissions,proto3" json:"min_submissions,omitempty"`
	DataMaxAge          int64  `protobuf:"varint,2,opt,name=data_max_age,json=dataMaxAge,proto3" json:"data_max_age,omitempty"`
	MaxMetadataSize     uint32 `protobuf:"varint,3,opt,name=max_metadata_size,json=maxMetadataSize,proto3" json:"max_metadata_size,omitempty"`
	BondDenom           string `protobuf:"bytes,4,opt,name=bond_denom,json=bondDenom,proto3" json:"bond_denom,omitempty"`
	BondMinAmount       string `protobuf:"bytes,5,opt,name=bond_min_amount,json=bondMinAmount,proto3" json:"bond_min_amount,omitempty"`
	BondReleaseCooldown int64  `protobuf:"varint,6,opt,name=bond_release_cooldown,json=bondReleaseCooldown,proto3" json:"bond_release_cooldown,omitempty"`
	// max_topics_per_block bounds how many topics may be aggregated per
	// EndBlock; the rest carry over to the next block. Keeps gas
	// predictable as topic count grows.
	MaxTopicsPerBlock uint32 `protobuf:"varint,7,opt,name=max_topics_per_block,json=maxTopicsPerBlock,proto3" json:"max_topics_per_block,omitempty"`
	// max_submissions_per_topic bounds how many submissions a single
	// aggregation may consume; defends against a topic with thousands of
	// providers eating the block.
	MaxSubmissionsPerTopic uint32 `protobuf:"varint,8,opt,name=max_submissions_per_topic,json=maxSubmissionsPerTopic,proto3" json:"max_submissions_per_topic,omitempty"`
}

